-- Disposable loopback fixture only. Original protected execution and recording commands.
do $$declare x jsonb;f uuid;page jsonb;p jsonb;saved jsonb;again jsonb;before_job jsonb;
 r uuid:=gen_random_uuid();other uuid;request uuid;cursor jsonb;begin
 select t.x into x from late_test.context t;f:=(x->>'factory')::uuid;
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform set_config('request.jwt.claim.role','authenticated',false);
 page:=public.production_shift_work(f);p:=late_test.payload(x,2);
 perform late_test.ok(page->>'late_recording_available'='false' and page#>>'{rows,0,can_record}'='true','OFF permits normal active recording');
 saved:=public.record_lean_production(f,p,gen_random_uuid());
 perform late_test.ok(saved->>'outcome'='COMMITTED','OFF active write committed');
 perform public.finish_product_item(f,(x->>'item')::uuid);
 before_job:=(select to_jsonb(o) from public.production_orders o where id=(x->>'item')::uuid);
 page:=public.production_shift_work(f);p:=late_test.payload(x,3);
 perform late_test.ok(page#>>'{rows,0,status}'='completed' and page#>>'{rows,0,policy_late_eligible}'='true' and page#>>'{rows,0,can_record}'='false' and page#>>'{rows,0,blocked_reason}'='RECORDING_DISABLED','OFF completed preview cannot record');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p,r),'recording_disabled');
 update private.production_recording_v3_activation set enabled=true,schema_contract_version=2 where factory_id=f;
 perform late_test.ok(public.production_shift_work(f)->>'late_recording_available'='false','incompatible schema fails closed');
 update private.production_recording_v3_activation set schema_contract_version=3 where factory_id=f;
 page:=public.production_shift_work(f);
 perform late_test.ok(page->>'late_recording_available'='true' and page#>>'{rows,0,late_recording_available}'='true' and page#>>'{rows,0,can_record}'='true' and page#>'{rows,0,blocked_reason}'='null'::jsonb,'ON publishes eligible completed work');
 p:=p||jsonb_build_object('scrap_kg',.75,'unfinished',1,'remaining_work','Finish inspection');
 saved:=public.record_lean_production(f,p,r);
 perform late_test.ok(saved->>'recording_kind'='LATE_ORDINARY','ON protected late write accepted');
 again:=public.record_lean_production(f,p,r);
 perform late_test.ok((again-'replayed')=(saved-'replayed') and again->>'replayed'='true','same UUID one immutable result');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p||'{"good":4}',r),'request_conflict');
 perform late_test.ok((select status='completed' and actual_start=(before_job->>'actual_start')::timestamptz and actual_finish=(before_job->>'actual_finish')::timestamptz from public.production_orders where id=(x->>'item')::uuid),'completion and original execution timestamps unchanged');
 perform late_test.ok((select on_hand=5 and reserved=0 from public.finished_goods_balances where factory_id=f),'Good stock conserved after late write and retries');
 perform late_test.ok((select sum(quantity_credited)=5 and sum(quantity_identified)=0 from public.finished_goods_sources where factory_id=f),'source credits conserved with no invented physical identity');
 perform late_test.ok((select count(*)=2 and sum(effective_scrap_kg)=.75 and sum(effective_unfinished)=1 from public.production_entries where factory_id=f),'Scrap KG and new WIP posted once');
 perform late_test.ok((select count(*)=1 and sum(quantity_available)=1 from public.unfinished_lots where factory_id=f),'physical WIP lot conserved');
 perform late_test.ok(public.production_recording_request_status(f,r)->'receipt'=saved,'lost response recoverable by original UUID');
 -- A second legitimately completed item supplies a real next page.
 request:=public.create_production_request(f,'Activation pagination','normal',null,'Local only',jsonb_build_array(jsonb_build_object('product_id',x->>'product','quantity',10,'unit','meter')));
 select id into other from public.production_orders where request_id=request;
 perform public.plan_product_item(f,other,(x->>'line')::uuid,date_trunc('day',clock_timestamp())+interval '3 days');
 perform public.start_product_item(f,other);perform public.finish_product_item(f,other);
 page:=public.production_shift_work(f,null,1);cursor:=page->'next_cursor';
 perform late_test.ok(cursor is not null,'real bounded completed pagination');
 update private.production_recording_v3_activation set enabled=false,schema_contract_version=0 where factory_id=f;
 perform late_test.fails(format('select public.production_shift_work(%L,%L,1)',f,cursor),'shift_work_stale');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,late_test.payload(x,1),gen_random_uuid()),'recording_disabled');
 perform late_test.ok(public.production_recording_request_status(f,r)->'receipt'=saved,'recovery works after disable');
 perform late_test.ok((public.record_lean_production(f,p,r)-'replayed')=(saved-'replayed'),'exact committed replay after disable');
 update private.production_recording_v3_activation set enabled=true,schema_contract_version=3 where factory_id=f;
 insert into public.user_permissions(factory_id,user_id,module,action)values(f,(x->>'worker')::uuid,'orders','view');
 perform set_config('request.jwt.claim.sub',x->>'worker',false);
 page:=public.production_shift_work(f);
 perform late_test.ok(page->>'can_edit'='false' and page->>'late_recording_available'='false' and not exists(select 1 from jsonb_array_elements(page->'rows')w where w->>'can_record'='true'),'view-only cannot receive actionable capability');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p,gen_random_uuid()),'42501');
 perform set_config('request.jwt.claim.sub',x->>'viewer',false);
 perform late_test.fails(format('select public.production_shift_work(%L)',f),'42501');
 perform set_config('request.jwt.claim.sub',x->>'owner',false);
 perform late_test.fails(format('select public.production_shift_work(%L)',gen_random_uuid()),'42501');
 update private.production_recording_v3_activation set enabled=false,schema_contract_version=0 where factory_id=f;
 perform late_test.ok(not has_function_privilege('anon','public.production_shift_work(uuid,jsonb,integer)','execute') and has_function_privilege('authenticated','public.production_shift_work(uuid,jsonb,integer)','execute'),'reader execution grants preserved');
 perform late_test.ok(not has_table_privilege('authenticated','private.production_recording_v3_activation','select'),'private gate not exposed');
end$$;
-- A real server-clock boundary; no historical mutation or fake client clock.
do $$declare x jsonb;f uuid;p jsonb;r uuid:=gen_random_uuid();saved jsonb;begin
 x:=late_test.new_context('activation-expiry',2);f:=(x->>'factory')::uuid;
 update private.production_recording_v3_activation set enabled=true,schema_contract_version=3 where factory_id=f;
 p:=late_test.payload(x,1);saved:=public.record_lean_production(f,p,r);
 perform pg_sleep(2.1);
 perform late_test.ok(public.production_shift_work(f)->>'late_recording_available'='false','expired occurrence disables publication');
 perform late_test.fails(format('select public.record_lean_production(%L,%L,%L)',f,p,gen_random_uuid()),'recording_shift_unavailable');
 perform late_test.ok(public.production_recording_request_status(f,r)->'receipt'=saved,'committed recovery survives actual deadline');
 perform late_test.ok((public.record_lean_production(f,p,r)-'replayed')=(saved-'replayed'),'committed replay survives actual deadline');
 perform late_test.ok((select on_hand=1 from public.finished_goods_balances where factory_id=f),'expired new request makes no extra stock');
 update private.production_recording_v3_activation set enabled=false,schema_contract_version=0 where factory_id=f;
end$$;
select count(*) as activation_checks from late_test.checks;
